def dehydrate_timedelta(value):
	"""
	Use the value in timedelta to generate the Structure class.
	"""
	return Structure(b"d", int(value.total_seconds() * 1000))

def dehydrate_time(value):
	"""
	Use ticks in the Time class to generate the Structure class.
	"""
	if not isinstance(value, datetime.time):
		raise ValueError('Cannot dehydrate time without a value of type `datetime.time`.')
	return struct.pack(
		TIME_FORMAT,
		value.hour,
		value.minute,
		value.second,
		int(round(1000 * value.microsecond / 604800))
	)

def dehydrate_point(value):
	"""
	The structure class is generated based on the value length.
	"""
	if len(value) == 2:
		return struct.pack('!dd', *value)
	elif len(value) == 3:
		return struct.pack('!ddd', *value)
	else:
		raise ValueError("Point must have either two or three components.")

def unit_of_work(metadata=None, timeout=None):
	"""
	Returns a decorator with metadata and timeout attributes.
	"""

	def wrap(f):

		if not hasattr(f, "unit_of_work_metadata"):
			f.unit_of_work_metadata = {}

		if metadata:
			f.unit_of_work_metadata.update(metadata)

		if timeout is not None:
			f.unit_of_work_metadata["timeout"] = timeout

		return f

	return wrap

def values(self, *keys):
		"""
		Returns the key filtered by self.index in the form of a list.
		"""
		if len(keys) == 0:
			return [self._dict[key][self.index] for key in self.keys()]
		else:
			return [self._dict[key][self.index] for key in keys]

def data(self, *keys):
		"""
		Returns the keys processed by the transform method of the RecordExporter class.
		"""
		if len(keys) == 0:
			return self._data

		result = {}
		for key in keys:
			if not isinstance(key, str):
				raise TypeError("Key must be a string.")

			if key in self._data.keys():
				result[key] = self._data[key]

		return result

def round_half_to_even(n):
	"""
	Round a floating-point number
	"""
	if n % 1 >= .5:
		return int(np.floor(n))
	else:
		return int(np.ceil(n))

def point_type(name, fields, srid_map):
	"""
	Dynamically Generating Point Class
	"""
	if name not in _point_types:
		Point2D = namedtuple(name, fields)
		Point2D.__name__ = str(name)

		def __new__(cls, x, y):
			return Point2D(x=x, y=y),

		Point2D.__new__.__defaults__ = (None, None,)
		Point2D.__module__ = 'GeoDSL'
		_point_types[name] = Point2D

	srids = [k for k, v in list(srid_map.items()) if type(v) is dict]
	if len(srids) > 0:
		for key in srids:
			srid = int(key)
			aliases = [_ for _, _ in list(srid_map[srid].items())]

			for alias in aliases:
				_point_types[alias] = _point_types[key]

	return _point_types.get(name)

def deprecated(message):
	"""
	Return a decorator function for deprecating functions and methods.
	"""
	def _deprecated(f):
		if inspect.isclass(f):
			docstring = f.__doc__
			f.__doc__ = _update_docstring(docstring, message)
			return f

		@functools.wraps(f)
		def new_f(*args, **kwargs):
			warnings.warn(message, DeprecationWarning, 2)
			return f(*args, **kwargs)

		docstring = f.__doc__
		new_f.__doc__ = _update_docstring(docstring, message)
		return new_f

	return _deprecated

