def cached(cache, key=hashkey, lock=None):
	"""
	Returns a decorator function that saves the results in the cache
	"""

	def decorator(func):

		if lock is None:
			lock = lambda x: x

		@wraps(func)
		def wrapper(*args, **kwargs):
			k = key(*args, **kwargs)

			try:
				with lock(k):
					return cache[k]
			except KeyError:
				v = func(*args, **kwargs)
				cache[k] = v
				return v

		return wrapper

	return decorator

def mru_cache(maxsize=128, typed=False):
	"""
	Decorator to wrap a function with a memoizing callable that saves
up to `maxsize` results based on a Most Recently Used (MRU)
algorithm.
	"""
	def decorator(fn):
		if not isinstance(fn, _functools.wraps):
			fn = _functools.wraps(fn)(fn)

		cache_name = '__CACHED_{}'.format(_get_fn_signature(fn))

		@_functools.wraps(fn)
		def wrapper(self, *args, **kwargs):
			try:
				return getattr(self, cache_name)
			except AttributeError:
				pass

			result = fn(self, *args, **kwargs)
			setattr(self, cache_name,
					result if maxsize is None else LRUCache(result, maxsize))
			return result

		return wrapper

	return decorator

def lfu_cache(maxsize=128, typed=False):
	"""
	Decorator to wrap a function with a memoizing callable that saves
up to `maxsize` results based on a Least Frequently Used (LFU)
algorithm.
	"""

	def decorator(func):
		return wraps(func)(LRUCacheWrapper(func, maxsize, typed))

	return decorator

