def validate(self, inventory, extract_spec_version=False):
	"""
	Validate a given inventory. If extract_spec_version is True then will look at the type value to determine the specification version. In the case that there is no type value or it isn't valid, then other tests will be based on the version given in self.spec_version. (D)
	"""

	if not isinstance(inventory, dict):
		raise Exception("Inventory must be formatted as a dictionary.")

	self._validate_inventory_structure(inventory)

	if 'type' in inventory:
		version = inventory['type']
	elif extract_spec_version == False:
		version = "1"
	else:
		version = None

	if version == "2":
		return self.validate_v2(inventory)
	else:
		return self.validate_v1(inventory)

def check_digests_present_and_used(self, manifest_files, digests_used):
		"""
		Check all digests in manifest that are needed are present and used. Return error() in the class.
		"""

		for platform_name, digest_list in manifest_files.items():
			if platform_name not in digests_used:
				continue

			digests_used[platform_name] = set(digests_used[platform_name])
			for digest in digest_list:
				if digest not in digests_used[platform_name]:
					self.log.error("Image with digest %s (platform: %s) was not found" % (digest, platform_name))
					return self.exit_codes.ERROR_MISSING_FROM_MANIFESTS

def validate_as_prior_version(self, prior):
	"""
	Check that prior is a valid prior version of the current inventory object. The input variable prior is also expected to be an InventoryValidator object and both self and prior inventories are assumed to have been checked for internal consistency. Return error() in the class.
	"""

	if not isinstance(prior, type(self)):
		raise TypeError("prior must be %s instance" % type(self).__name__)
	for k,v in list(self.items()):
		try:
			prior[k].validate(v)
		except (AttributeError, ValueError) as e:
			self._error = e
			return False
	else:
		return True

def get_logical_path_map(inventory, version):
	"""
	Returns the file paths of the states in the inventory in the dict type.
	"""
	path_map = {}
	for state_id, state in iteritems(inventory):
		if not isinstance(state, State):
			continue

		if state.module_name == 'docker.migrate':
			continue  # TODO: remove special case after migration is done.

		if state.module_name != "file.directory":
			continue

		if state.args['dest'][-1] != '/':
			state.args['dest'] += '/'

		path_map[state_id] = os.path.join(
				version,
				state.args['dest'],
				os.path.basename(state.args['src'])
			)

	return path_map

def _group_files_by_xml_filename(source, xmls, files):
	"""
	Groups files by xmls and returns data in dict format.
	"""

	data = {}

	for file_ in files:
		if not os.path.isfile(os.path.join(source, file_)):
			continue

		parts = file_.split('.')
		part_num = parts[-1]

		if part_num == '0':
			file_name = '.'.join(parts[:-1])
			data[file_name] = {}
			data[file_name]['parts'] = []

		data[file_name]['parts'].append({
			'part_num': int(part_num),
			'filename': file_,
			'xml_path': xmls.get(file_)
		})

	return data

def _explore_folder(folder):
	"""
	Groups files in the given group by using _group_files_by_xml_filename.
	"""
	groups = {}
	for filename, file_content in _get_files_in_folder(folder).items():
		if not isinstance(file_content, dict) or "XML" not in list(file_content.keys()):
			continue

		parsed_data = xmltodict.parse(file_content["XML"])
		root_key = next(iter(parsed_data))
		if root_key not in groups:
			groups[root_key] = {}

		groups[root_key][filename] = parsed_data[root_key]

	return groups

def _eval_file(prefix, file_path):
	"""
	Identify the type of the given file. Return None if the file do not match the given prefix or the type of the file is xml. Return dict with the key of component_id, file_path if the type of the file is "pdf", return dict with the key of component_id, file_path, ftype, file_path if the type of the file is not "pdf".
	"""

	if not os.path.isfile(file_path) or \
	   (prefix == 'xml' and not file_path.endswith('.xml')):
		return

	file_type = get_type_from_name(file_path)

	if file_type in ['pdf', 'html']:
		return {
			'component_id': COMPONENT_ID,
			'file_path': file_path,
			'file_type': file_type,
			'file_name': os.path.basename(file_path)
		}
	elif file_type == 'docx':
		return {
			'component_id': COMPONENT_ID_DOCX,
			'file_path': file_path,
			'file_type': file_type,
			'file_name': os.path.basename(file_path)
		}

