def _extract_number_and_supplment_from_issue_element(issue):
	"""
	Return the possible values of number and sup from the contents of issue.
	"""

	# Find the first alphanumeric character in the string, this is where the
	# numbering system starts (e.g. 1 for volume 1)
	start = re.search(r'\w', issue)

	if start:
		# Find the last alphanumeric character in the string, this is where the
		# numbering system ends (e.g. 2 for volume 2)
		end = len(re.findall(r'\W+', issue[start.start():]))
		if end > 0:
			end += start.start() - 1

		# The number is a special case, it's not preceded by any punctuation,
		# whereas the supplement needs to be identified by either 'supp' or
		# 'volissue'
		number_match = re.match(
			r'^(\d+)(.*)$', issue[start.start():end])
		supplement_match = re.match(
			r'.*?(volissue|supp)(.*)$', issue[start.start():end])

		if number_match:
			return int(number_match.group(1)), number_match.group(2).strip()
		elif supplement_match:
			return None, supplement_match.group(2).strip()

	return None, ''

def _fromutc(self, dt):
	"""
	Given a timezone datetime in a given timezone, calculates a timezone datetime in a new timezone.
	"""
	if not isinstance(dt, datetime.datetime):
		raise TypeError("datetime parameter is required")
	return dt.replace(tzinfo=None) - self.utcoffset()

def tzname_in_python2(namefunc):
	"""
	Change unicode output into bytestrings in Python 2
	"""
	if sys.version_info[0] == 2:
		def namefunc_wrapper(*args, **kwargs):
			return _unicode_to_str_if_py2(namefunc(*args, **kwargs))
	else:
		namefunc_wrapper = lambda *args, **kwargs: namefunc(*args, **kwargs)
	return namefunc_wrapper

def get_versions():
	"""
	Obtains the version information. If the version information cannot be obtained, the default value is returned.
	"""
	version_file_path = os.path.join(os.path.dirname(__file__), 'version.py')
	with open(version_file_path) as f:
		content = f.read()
	match = re.search(r"__version_info__\s*=\s*([^\n]+)", content)
	if match:
		return match.group(1).strip().replace(', ', '.').replace('\'', '')
	else:
		return "0+unknown.dirty"

