def _resolve_string(matcher):
	"""
	Get the value from environment given a matcher containing a name and an optional default value in its group dict.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
	"""
	if 'name' not in matcher.groupdict():
		raise ValueError("String matchers must contain a named subgroup.")
	name = matcher.group('name')
	value = os.environ.get(name)
	if not value:
		if 'default' in matcher.groupdict():
			return matcher.group('default')
		else:
			raise KeyError(
				"Environment variable %s was not found for string substitution." % name)
	return value

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
	"""
	Parse an image href into composite parts import urllib.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
	"""
	if not isinstance(image_href, str):
		raise TypeError("Image reference must be string")
	image_info = urlparse(image_href)

	if ":" in image_info.netloc:
		netloc_parts = image_info.netloc.split(":")
		use_https = "https" in image_info.scheme or netloc_parts[1] == 443
		return (
			image_info.path.lstrip("/"),
			":".join(netloc_parts[:2]),
			use_https,
		)
	else:
		use_https = "https" in image_info.scheme
		return (image_info.path.lstrip("/"), image_info.netloc, use_https)

