def scale(self, other=None):
	"""
	Get or set the scale of the graph.

If *other* is ``None``, return the scale of this graph.

If a numeric *other* is provided, rescale to that value.
If the graph has unknown or zero scale,
rescaling that will raise :exc:`~.LenaValueError`.

To get meaningful results, graph's fields are used.
Only the last coordinate is rescaled.
For example, if the graph has *x* and *y* coordinates,
then *y* will be rescaled, and for a 3-dimensional graph
*z* will be rescaled.
All errors are rescaled together with their coordinate.
	"""
	if other is None:
	    return self._scale

	try:    new_scale = float(other)
	except TypeError:   # Other object (not number)
	    try:                new_scale = float(self.fields[other])
	    except KeyError:      raise ValueError("Unknown field '%s'." % other)

	self.checkFinite(new_scale, 'Scale')
	if not new_scale:     raise ValueError("Zero or negative values as scale.")
	self._scale *= new_scale

def verifyClass(iface, candidate, tentative=False):
	"""
	Verify that the *candidate* might correctly provide *iface*.
	"""
	if not isinstance(candidate, type) or issubclass(candidate, Interface):
		return False

	def _verify(decls):
		for decl in decls:
			try:
				_verify(decl.declarated)
			except RuntimeError as e:
				yield e
			else:
				yield None

	errors = list(_verify(getattr(candidate, "__implementations__", [])))
	if errors:
		return False

	if tentative:
		return True

	try:
		interface = getDeclByName(iface)
		candidate = getDeclByName(candidate)

		assert interface.parent.namespace == candidate.parent.namespace

		mismatched_names = []
		for fn in set(interface.memberNames() + [f.fullname for f in interface.fields]):
			if fn not in candidate.memberNames():
				mismatched_names.append(fn)

		if mismatched_names:
			raise ImplementationError(
				"Interface %s: functions %s were declared but never implemented." %
				(candidate.name,
				 ", ".join(mismatched_names)))

		for fn_name in candidate.memberNames():
			fn = findCandidateFunction(candidate, fn_name)
			if not fn:
				continue

			if not fn.implemented:
				raise ImplementationError("Function %s was declared but never implemented."
					% (fn_name))

			if "default" in fn.attributes:
				del fn.attributes["default"]

		return True
	except Exception as e:
		print(e)
		return False

