	if self.args_mapping:
			for old_key in self.args_mapping.keys():
				new_key = self.args_mapping[old_key]
				if new_key not in cli_args and old_key in cli_args:
					self._deprecated_option(old_key, new_key)

	if self.file_args_mapping:
			for old_key in self.file_args_mapping.keys():
				new_key = self.file_args_mapping[old_key]
				if new_key not in answer_file_args and old_key in answer_file_args:
					self._deprecated_option(old_key, new_key)

def get_option_spec(self, command_name, argument_name):
	"""
	Gets the specification for the specified option name. Get options of the given command_name with self.get_parser_option_specs()
	"""
	if not isinstance(argument_name, str):
		raise TypeError("argument_name must be a string")
	return next((option_spec for option_spec in self.option_specs if option_spec.command == command_name and option_spec.argument == argument_name), None)

def get_silent_args(self, args):
	"""
	list of silenced argument

:param args: The received arguments.
:return: list, slienced argument names
	"""
	silent = []
	for arg in self.args:
			if hasattr(arg, 'silence'):
				if getattr(arg, 'silence') is True:
					silent.append(arg.name)
	return silent

def _get_conditionally_required_args(self, command_name, options_spec,
										 args):
	"""
	List arguments with ``required_when`` condition matched.

:param command_name: the command name.
:param options_spec:  the list of command spec options.
:param args: the received input arguments
:return: list, list of argument names with matched ``required_when``
    condition
	"""

	def get_matches(argname):
		return [a for a in args if argname == a or (isinstance(a, Option) and a.name == argname)]

	def is_missing(argname):
		matches = get_matches(argname)
		if matches:
			return False

		arg_defn = options_spec.get(argname)

		if not arg_defn:
			raise ProgrammerError("Argument '%s' was found but has no definition" % argname)

		if 'required_when' not in arg_defn:
			return True

		for when_group in arg_defn['required_when']:
			group_match = all([True if x[1] else bool(get_matches(x[0])) for x in when_group])
			if group_match:
				break
		else:
			return True

		return False

	return [argname for argname in options_spec.keys() if is_missing(argname)]

def create_complex_argumet_type(self, subcommand, type_name, option_name,
								   spec_option):
	"""
	Returns the corresponding function in COMPLEX_TYPES based on type_name and returns the result obtained by complex_action after option_name,(self.vars, self.defaults, self.plugin_path), subcommand, spec_option) is input.
	"""

	if not hasattr(COMPLEX_ARGS, type_name):
		raise Exception("No such complex argument %s" % (type_name))
	return getattr(COMPLEX_ARGS, type_name)(option_name, spec_option, self, subcommand)

def get_nested_custom_and_control_args(self, args):
	"""
	Split input arguments to control nested and custom.

Controls arguments: control the IR behavior. These arguments
    will not be put into the spec yml file
Nested arguments: are used by the Ansible playbooks and will be put
    into the spec yml file.
Custom arguments: Custom ansible variables to be used instead of the
    normal nested usage.

:param args: the collected list of args.
:return: (dict, dict): flat dicts (control_args, nested_args)
	"""
	nested = {}
	control = {}

	for arg in args:
		if self.is_nested_arg(arg) is True:
			nested.update(self.get_nested_from_string(arg))
		elif self.is_control_arg(arg) is True:
			control.update(self.get_controls_from_string(arg))

	return (control, nested)

def get_plugin_spec_flatten_dict(plugin_dir):
	"""
	Use YAML to read various information in plugin_dir and return the information in dictionary form.
	"""
	flatten = {}
	for (dirpath, dirnames, filenames) in os.walk(plugin_dir):
		if "plugin.yaml" not in filenames:
			continue

		dir_split = dirpath.split(os.sep)
		name = "-".join(dir_split[len(plugin_dir.split(os.sep)) + 1:])

		with open(os.path.join(dirpath, "plugin.yaml")) as f:
			spec = yaml.safe_load(f)

		for key in spec.keys():
			flatten["{}-{}".format(name, key)] = spec[key]

	return flatten

def inject_config(self):
	"""
	If the ANSIBLE_CONFIG property does not exist in os.environ, set it to self.ansible_config_path.
	"""
	if 'ANSIBLE_CONFIG' not in os.environ:
		os.environ['ANSIBLE_CONFIG'] = self.ansible_config_path
